package net.civeira.phylax.common.exception;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.value.validation.AbstractFailList;

@DisplayName("AbstractFailsException message")
class AbstractFailsExceptionMessageUnitTest {

  @Test
  @DisplayName("Should keep the plain message when there are no fails")
  void shouldKeepPlainMessageWithoutFails() {
    // Arrange / Act — an exception over an empty fail list
    AbstractFailsException ex = new AbstractFailsException("Nothing", new AbstractFailList()) {
      private static final long serialVersionUID = 1L;
    };

    // Assert — the message has no fail suffix
    assertEquals("Nothing", ex.getMessage());
    assertTrue(ex.isEmpty());
  }
}
